[IO.File]::WriteAllText((Join-Path $PWD 'tests.yml'), "# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# .github/workflows/tests.yml: the tests on Linux, macOS and Windows, each job with its own`n# test servers, started, used and stopped in steps, and the server log kept when a step fails.`nname: Tests`non: [push, pull_request]`njobs:`n  test:`n    strategy:`n      fail-fast: false`n      matrix:`n        os: [ubuntu-latest, macos-latest, windows-latest]`n    runs-on: `${{ matrix.os }}`n    defaults:`n      run:`n        shell: bash`n    steps:`n      - uses: actions/checkout@v4`n      # surl and curl built from source, until they publish releases.`n      - uses: actions/checkout@v4`n        with: { repository: StewartScottRogers/Surl, path: tools/Surl }`n      - uses: actions/checkout@v4`n        with: { repository: StewartScottRogers/Curl, path: tools/Curl }`n      - uses: actions/setup-dotnet@v4`n        with: { dotnet-version: `"10.0.x`" }`n      - name: Build surl and curl`n        run: |`n          dotnet build tools/Surl/Application/Surl.Console -c Release -o tools/bin/surl -v q`n          dotnet build tools/Curl/Curl.Console -c Release -o tools/bin/curl -v q`n          echo `"`${{ github.workspace }}/tools/bin/surl`" >> `"`$GITHUB_PATH`"`n          echo `"`${{ github.workspace }}/tools/bin/curl`" >> `"`$GITHUB_PATH`"`n      - name: Start test servers`n        run: sh ci/start-servers.sh`n      - name: Run tests`n        run: sh ci/tests.sh`n      - name: Stop test servers`n        if: always()`n        run: sh ci/stop-servers.sh`n      - name: Upload the server log`n        if: failure()`n        uses: actions/upload-artifact@v4`n        with:`n          name: surl-log-`${{ matrix.os }}`n          path: surl.log`n")
[IO.File]::WriteAllText((Join-Path $PWD 'ci/start-servers.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Step `"Start test servers`": start surl in the background on free ports for HTTP and SMTP,`n# keep its process ID in surl.pid for the stop step, and hand the URLs to later steps by`n# appending them to the file `$GITHUB_ENV names. Fails the step if surl does not start.`n: > listening.txt`nsurl -v --log-file surl.log --directory site --mail-domain example.com \`n  --mailbox app@example.com:secret http://127.0.0.1:0/ smtp://127.0.0.1:0/ \`n  < /dev/null > listening.txt 2> surl.err &`npid=`$!`necho `"`$pid`" > surl.pid`n`ntries=0`nuntil [ `"`$(grep -c '^Listening on ' listening.txt)`" -eq 2 ]; do`n  if ! kill -0 `"`$pid`" 2>/dev/null; then`n    wait `"`$pid`"; code=`$?`n    cat surl.err >&2`n    echo `"surl did not start: exit `$code`" >&2`n    exit `"`$code`"`n  fi`n  tries=`$((tries + 1))`n  if [ `"`$tries`" -ge 100 ]; then kill `"`$pid`"; echo `"surl did not start in 10 s`" >&2; exit 1; fi`n  sleep 0.1`ndone`nsed -n -e 's|^Listening on \(http://.*\)|HTTP_URL=\1|p' \`n       -e 's|^Listening on \(smtp://.*\)|SMTP_URL=\1|p' listening.txt | tr -d '\r' >> `"`$GITHUB_ENV`"`n")
[IO.File]::WriteAllText((Join-Path $PWD 'ci/tests.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Step `"Run tests`": fetch the greeting over HTTP and mail it over SMTP, to the URLs the start`n# step put in the environment. The first failure ends the step with curl's exit code.`n# Usage: sh ci/tests.sh [<mailbox password>]`nset -e`ngreeting=`$(curl -fsS `"`${HTTP_URL}greeting.txt`")`nprintf 'Subject: Greeting\r\n\r\n%s\r\n' `"`$greeting`" |`n  curl -sS -u `"app@example.com:`${1:-secret}`" --mail-from app@example.com \`n    --mail-rcpt app@example.com -T - `"`${SMTP_URL}example.com`"`necho `"mailed: `$greeting`"`n")
[IO.File]::WriteAllText((Join-Path $PWD 'ci/stop-servers.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Step `"Stop test servers`", run whatever the steps before it did: stop the surl the start step`n# left running and wait until it has gone, so its ports are free and its log is complete.`n[ -f surl.pid ] || { echo `"no surl to stop`"; exit 0; }`npid=`$(cat surl.pid)`nkill `"`$pid`" 2>/dev/null || { echo `"surl had already ended`"; exit 1; }`ntries=0`nwhile kill -0 `"`$pid`" 2>/dev/null; do`n  tries=`$((tries + 1))`n  if [ `"`$tries`" -ge 150 ]; then echo `"surl did not stop in 15 s`" >&2; exit 1; fi`n  sleep 0.1`ndone`necho `"stopped surl`"`n")
[IO.File]::WriteAllText((Join-Path $PWD 'steps.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Stands in for the runner, which a recipe cannot start: runs the workflow's three server`n# steps in order, each in a shell of its own; sets what a step appended to `$GITHUB_ENV for`n# the steps after it; runs the stop step always; and keeps surl.log when a step failed, as`n# the upload step would. Exits as the job would: 0, or the first failed step's code.`n# Usage: sh steps.sh [<mailbox password the tests use>]`nGITHUB_ENV=`$PWD/github.env; export GITHUB_ENV`n: > `"`$GITHUB_ENV`"`nstatus=0`nsh ci/start-servers.sh || status=`$?`nif [ `"`$status`" -eq 0 ]; then`n  set -a; . `"`$GITHUB_ENV`"; set +a`n  sh ci/tests.sh `"`$@`" || status=`$?`nfi`nsh ci/stop-servers.sh || [ `"`$status`" -ne 0 ] || status=1`nif [ `"`$status`" -ne 0 ]; then mkdir -p artifact && cp surl.log artifact/ && echo `"kept surl.log`"; fi`nexit `"`$status`"`n")
[IO.File]::WriteAllText((Join-Path $PWD 'steps-of.py'), "# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Prints each step of the workflow's test job: its condition, then what it runs or uses.`nimport sys, yaml`njob = yaml.safe_load(open(sys.argv[1], encoding=`"utf-8`"))[`"jobs`"][`"test`"]`nprint(`"runs-on:`", job[`"runs-on`"], `"for`", `", `".join(job[`"strategy`"][`"matrix`"][`"os`"]))`nfor step in job[`"steps`"]:`n    what = step.get(`"run`", step.get(`"uses`", `"`")).strip().splitlines()[0]`n    print(step.get(`"if`", `"-`"), `"|`", what)`n")
sh steps.sh
